func oftWord(words *port.Cells, start int32, spanlen int32, run int32, conf int32, flags int32) int32 {
	var w int32 = evidence.OwNew(words, 1, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, start, spanlen, 0, conf, -1)
	evidence.OwSet(words, w, evidence.OwfRun(), run)
	evidence.OwSet(words, w, evidence.OwfFlags(), flags)
	return w
}

func oftRun(runs *port.Cells, first int32, count int32, pass int32) int32 {
	var r int32 = evidence.OrNew(runs, 1, 0)
	evidence.OrSet(runs, r, evidence.OrfPass(), pass)
	evidence.OrSet(runs, r, evidence.OrfWfirst(), first)
	evidence.OrSet(runs, r, evidence.OrfWcount(), count)
	return r
}

func TestDistinctReadingsIgnoreConfidenceOnlyDuplicatesAndExcludedPasses(emonT *testing.T) {
	var words *port.Cells = port.NewCells()
	var runs *port.Cells = port.NewCells()
	var text *port.Cells = port.NewCells()
	var reads *port.Cells = port.NewCells()
	var refs *port.Cells = port.NewCells()
	port.CellsPush(text, 65)
	oftWord(words, 0, 1, 0, 300, 1)
	oftWord(words, 0, 1, 1, 950, 1)
	oftWord(words, 0, 1, 2, 990, 1)
	oftRun(runs, 0, 1, 1)
	oftRun(runs, 1, 1, 10)
	oftRun(runs, 2, 1, 8)
	port.AssertEq(emonT, ofuse.OfReadings(runs, words, text, 1, reads, refs), 1, "identical reading is one vote; re-rotated pass excluded")
	port.AssertEq(emonT, port.CellsAt(reads, 0), 0, "first recorded reading supplies verbatim source")
	port.AssertEq(emonT, port.CellsLen(refs), 1, "duplicate words are not alignment nodes")
}

