func TestSlotAggregatesSplitSequencesAndKeepsVerbatimBestSource(emonT *testing.T) {
	var words *port.Cells = port.NewCells()
	var text *port.Cells = port.NewCells()
	var reads *port.Cells = port.NewCells()
	var rows *port.Cells = port.NewCells()
	var parents *port.Cells = port.NewCells()
	var selected *port.Cells = port.NewCells()
	var candidates *port.Cells = port.NewCells()
	var refs *port.Cells = port.NewCells()
	var seq *port.Cells = port.NewCells()
	port.CellsPush(text, 49)
	port.CellsPush(text, 50)
	port.CellsPush(text, 46)
	port.CellsPush(text, 79)
	port.CellsPush(text, 79)
	port.CellsPush(text, 46)
	port.CellsPush(text, 48)
	port.CellsPush(text, 48)
	oftWord(words, 0, 5, 0, 400, 0)
	oftWord(words, 0, 2, 1, 800, 2)
	oftWord(words, 5, 3, 1, 800, 2)
	oftWord(words, 0, 2, 2, 900, 2)
	oftWord(words, 5, 3, 2, 900, 2)
	port.CellsPush(selected, 0)
	port.CellsPush(rows, 0)
	port.CellsPush(rows, 1)
	port.CellsPush(rows, 2)
	port.CellsPush(rows, 3)
	port.CellsPush(rows, 4)
	port.CellsPush(parents, 0)
	port.CellsPush(parents, 0)
	port.CellsPush(parents, 0)
	port.CellsPush(parents, 0)
	port.CellsPush(parents, 0)
	port.CellsPush(reads, 2)
	port.CellsPush(reads, 2)
	port.CellsPush(reads, 2)
	port.CellsPush(reads, 1)
	port.CellsPush(reads, 0)
	port.CellsPush(reads, 2)
	port.AssertEq(emonT, ofuse.OfCandidates(words, text, rows, parents, 0, selected, reads, candidates, refs, seq), 2, "incumbent and one aggregated split sequence")
	port.AssertEq(emonT, ofuse.OfCget(candidates, 1, 3), 2, "distinct readings agree")
	port.AssertEq(emonT, ofuse.OfCget(candidates, 1, 4), 900, "maximum reading mean confidence")
	port.AssertEq(emonT, ofuse.OfCget(candidates, 1, 0), 1, "earliest reading retains source sequence")
	port.AssertEq(emonT, ofuse.OfCget(candidates, 1, 2), 2, "split source rows retained")
	port.AssertEq(emonT, port.CellsAt(refs, ofuse.OfCget(candidates, 1, 1)), 1, "verbatim first word")
	port.AssertEq(emonT, port.CellsAt(refs, ofuse.OfCget(candidates, 1, 1)+1), 2, "verbatim second word")
	port.AssertEq(emonT, ofuse.OfChoice(candidates, 1), -1, "malformed split decimal is blocked, never repaired")
}

