func TestChoiceTiesUseVotesThenConfidenceThenRunOrder(emonT *testing.T) {
	var c *port.Cells = port.NewCells()
	port.CellsPush(c, -1)
	port.CellsPush(c, 0)
	port.CellsPush(c, 0)
	port.CellsPush(c, 0)
	port.CellsPush(c, 0)
	port.CellsPush(c, 0)
	port.CellsPush(c, 0)
	port.CellsPush(c, 0)
	port.CellsPush(c, 9)
	port.CellsPush(c, 0)
	port.CellsPush(c, 1)
	port.CellsPush(c, 2)
	port.CellsPush(c, 800)
	port.CellsPush(c, 1)
	port.CellsPush(c, 0)
	port.CellsPush(c, 0)
	port.CellsPush(c, 3)
	port.CellsPush(c, 1)
	port.CellsPush(c, 1)
	port.CellsPush(c, 2)
	port.CellsPush(c, 800)
	port.CellsPush(c, 1)
	port.CellsPush(c, 0)
	port.CellsPush(c, 0)
	port.AssertEq(emonT, ofuse.OfChoice(c, 0), 2, "run order breaks exact tie independent of candidate table order")
	port.CellsSet(c, (1*ofuse.OfCstride())+4, 801)
	port.AssertEq(emonT, ofuse.OfChoice(c, 0), 1, "confidence breaks equal votes")
	port.CellsSet(c, (2*ofuse.OfCstride())+3, 3)
	port.AssertEq(emonT, ofuse.OfChoice(c, 0), 2, "votes outrank confidence")
	port.CellsSet(c, (1*ofuse.OfCstride())+4, 699)
	port.CellsSet(c, (2*ofuse.OfCstride())+4, 699)
	port.AssertEq(emonT, ofuse.OfChoice(c, 0), -1, "no low-confidence insertion")
}

